using System.Runtime.CompilerServices;
using UnityEngine;
using UnityEngine.UIElements;
namespace Veilbreak.Gui {
/// <summary>The fluid scale: the base text size, the gutters and the margins follow the panel's width (smaller boards get smaller values). UI Toolkit has no clamp() or calc(), so the scale is
/// stepped: <c>Fluid.uss</c> (generated by <c>Tools~/fluid.py</c> from <c>Tokens~/fluid.json</c>) has one class per step, <c>vb-fluid-&lt;width&gt;</c>, that overrides the type, spacing and layout tokens with
/// their value times the step's factor, and <see cref="Apply"/> puts the class for a width on the board's root, where every descendant inherits it. <see cref="SafeAreaRoot.Flags"/> applies it from the panel's
/// width each time it runs; popovers, which live on the panel root, copy it from their anchor (<see cref="Copy"/>). The factor is 0.92 at 320, 1 at the 390 reference, 1.06 at 430 and 1.18 from 600 up.</summary>
public static partial class VbFluid {
 public const string Prefix="vb-fluid-";
 static string[] built;
 static string[] classes=>built??=Build();
 static readonly ConditionalWeakTable<VisualElement,Held> held=new ConditionalWeakTable<VisualElement,Held>();
 sealed class Held {public int index=-1;}
 static string[] Build(){var c=new string[Steps.Length];for(int i=0;i<c.Length;i++)c[i]=Prefix+Steps[i];return c;}
 /// <summary>The index of the step for a panel <paramref name="width"/>: the widest step that is not wider than it (the narrowest step below the first).</summary>
 public static int StepIndex(float width){int index=0;for(int i=0;i<Steps.Length;i++)if(width>=Steps[i])index=i;return index;}
 /// <summary>The width of the step for a panel <paramref name="width"/> (320 for anything narrower, 600 for anything wider).</summary>
 public static int Step(float width)=>Steps[StepIndex(width)];
 /// <summary>The scale factor of the step for <paramref name="width"/>: every size, gutter and margin is its 390-unit value times this.</summary>
 public static float Factor(float width)=>Factors[StepIndex(width)];
 /// <summary><c>vb-fluid-320</c> … <c>vb-fluid-600</c>; the class for a panel <paramref name="width"/>.</summary>
 public static string ClassFor(float width)=>classes[StepIndex(width)];
 /// <summary>Puts the step class for <paramref name="width"/> on <paramref name="root"/> (and takes the old one off); true when the step changed. A width that is not a number or not positive changes nothing.</summary>
 public static bool Apply(VisualElement root,float width){
  if(root==null||float.IsNaN(width)||width<=0)return false;int index=StepIndex(width);var h=held.GetValue(root,_=>new Held());if(h.index==index)return false;
  if(h.index>=0)root.RemoveFromClassList(classes[h.index]);h.index=index;root.AddToClassList(classes[index]);return true;
 }
 /// <summary>The step class the nearest ancestor of <paramref name="e"/> (itself included) carries, or null.</summary>
 public static string ClassOf(VisualElement e){for(var p=e;p!=null;p=p.hierarchy.parent)if(held.TryGetValue(p,out var h)&&h.index>=0)return classes[h.index];return null;}
 /// <summary>Gives <paramref name="to"/> the step class <paramref name="from"/> works under (popovers on the panel root).</summary>
 public static void Copy(VisualElement from,VisualElement to){var c=ClassOf(from);if(c!=null)to.AddToClassList(c);}
}
}
